mapper.select:
SELECT A .ID AS RECORDID, A .STAFF_NAME, A .START_TIME AS STARTDATE, A .END_TIME AS ENDDATE, A .CREATE_TIME AS RECORDDATE, A .PROCESS_ID, A .DURATION AS VACATECOUNT, A .TYPE, A .CREATE_TIME FROM SMT_ASK_LEAVE_APPLICATION A
A.STAFF_BADGE =#{query.staffBadge}
ORDER BY A.CREATE_TIME DESC

select * from SMT_BREAKOFF_APPLICATION

where STAFF_BADGE=#{query.staffBadge}


	and type =#{query.type}


and REST_TIME=#{query.restTime}
